"""flash.sh for each way a phone takes its images, and the guarded flash command."""
import shlex
import subprocess
from pathlib import Path

from . import Exit
from .resolve import entry_warnings

HEADER = """#!/bin/sh
# Generated by ztConflo for {codename} ({name}). Overwrites: {targets}.
set -eu
cd "$(dirname "$0")"
"""


def targets(boot: dict) -> list[tuple[str, str]]:
    """(image, partition) pairs, in the order they are written."""
    method = boot["flash_method"]
    rootfs = boot.get("rootfs_target", "userdata")
    if method == "fastboot":
        return [("boot.img", boot.get("boot_partition", "boot")), ("rootfs.img", rootfs)]
    if method == "heimdall-bootimg":
        return [("boot.img", boot.get("heimdall_partition_kernel", "BOOT")), ("rootfs.img", rootfs)]
    if method == "heimdall-isorec":
        return [("kernel", boot.get("heimdall_partition_kernel", "KERNEL")),
                ("initramfs", boot.get("heimdall_partition_initfs", "RECOVERY")),
                ("rootfs.img", rootfs)]
    raise Exit(Exit.BUILD_FAILED, f"flash method '{method}' is not supported yet "
                                  "(fastboot, heimdall-bootimg and heimdall-isorec are)")


def script(entry: dict) -> str:
    boot = entry["boot"]
    pairs = targets(boot)
    out = HEADER.format(codename=entry["device"]["codename"], name=entry["device"]["name"],
                        targets=", ".join(p for _, p in pairs))
    method = boot["flash_method"]
    if method == "fastboot":
        for image, part in pairs:
            out += f"fastboot flash {shlex.quote(part)} {shlex.quote(image)}\n"
        out += "fastboot reboot\n"
    else:
        args = " ".join(f"--{shlex.quote(part)} {shlex.quote(image)}" for image, part in pairs)
        out += f"heimdall flash {args}\n"
    return out


def flash(out_dir: Path, entry: dict, ask=input, run=subprocess.run) -> None:
    sh = out_dir / "flash.sh"
    if not sh.is_file():
        raise Exit(Exit.BUILD_FAILED, f"no {sh}: run `ztconflo build {entry['device']['codename']}` first")
    pairs = targets(entry["boot"])
    print(f"Flashing {entry['device']['name']} ({entry['device']['codename']}) with {entry['boot']['flash_method']}.")
    for image, part in pairs:
        print(f"  {part:<16} <- {out_dir / image}")
    for w in entry_warnings(entry):
        print(f"\nWARNING: {w}\n")
    print("This erases everything on those partitions, including your data on "
          f"{entry['boot'].get('rootfs_target', 'userdata')}.")
    if ask("Type the codename to continue: ").strip() != entry["device"]["codename"]:
        print("Not flashed.")
        return
    run(["sh", str(sh)], check=True)
